#include "rxt_private.h"
#include "dbg.h"
#include "cmd.h"
#include "status.h"


/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static void rxt_oem_count (void * arg) ;
                                      
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/

void rxt_oem_lock (void * arg)
{
	rxt_oem_count (0) ;   
#if DBG_RXT == 1
	dbg_tx_text ("\nrxt oem lock") ; 
#endif
}

//--------------------------------------------------------------------------//

void rxt_oem_timeout_stop (void * arg)
{
    timeout_stop (rxt.lock_start_timeout) ;

    #if DBG_RXT == 1
        dbg_tx_text ("\nrxt oem lock_start_timeout stoped") ;
    #endif
}

//--------------------------------------------------------------------------//

static void rxt_oem_count (void * arg)
{
 	static UInt8 rxt_oem_count ;
	
    if(!timeout_test(rxt.lock_start_timeout))
      {
        if(++rxt_oem_count >= 3)
          {
        	cmd_q_insert ((Cmd_List)(INPUT_START | INPUT_ON), 500) ;
            timeout_stop (rxt.lock_start_timeout) ;
          }
      }
    else
      {
      rxt_oem_count = 1 ;
      timeout_start(rxt.lock_start_timeout) ;
      }
}


